; ROAD.ASM - MAX Q raster road (generated by mkroad.py from engine.asm + road_new.asm)
sext:   ld l,a                  ; HL = A sign-extended
        add a,a
        sbc a,a
        ld h,a
        ret

; quarter-square signed multiply, HL = B * C ; clobbers A,C,DE
mul8:   ld a,c
        xor $80
        ld h,a
        ld a,b
        xor $80
        ld l,a
        add a,h
        ld e,a
        ld a,SQPAGE
        adc a,0
        ld d,a
        ld a,l
        sub h
        jr nc,.p
        neg
.p:     ld l,a
        ld h,SQPAGE+1
        ld a,(de)
        sub (hl)
        ld c,a
        inc d
        inc d
        inc h
        inc h
        ld a,(de)
        sbc a,(hl)
        ld h,a
        ld l,c
        ret

compose:
        ld a,(SKYDIRTY)         ; restore the static sky only after a gate drew on it
        or a
        jr z,.nsky
        ld hl,SKYIMG
        ld de,BUFFER
        ld bc,TOPROW*32
        ldir
        xor a
        ld (SKYDIRTY),a
        inc a
        ld (HUDFORCE),a
        ld (TOPCHG),a
.nsky:  ; plain-sky rows at the top of the 3D view: no track, no skyline, no banner
        ld a,(SPLIT)
        sub SKYL_H+1
        jr c,.s0
        cp TOPROW
        jr nc,.s1
.s0:    ld a,TOPROW
.s1:    ld c,a                  ; C = limit
        ld hl,ROWCL+TOPROW
        ld b,TOPROW
.s2:    ld a,b
        cp c
        jr nc,.s3
        ld a,(hl)
        inc a
        jr nz,.s3
        inc l
        inc b
        jr .s2
.s3:    ld a,(BANT)
        or a
        jr z,.s4
        ld a,b
        cp 20
        jr c,.s4
        ld b,20
.s4:    ld a,b
        ld (SPLAIN),a
        ld a,(CLEAN)            ; still plain in BUFFER from last frame? then skip them
        cp b
        ld a,b
        jr nc,.s5
        ld a,TOPROW
.s5:    ld c,a
        ld a,(SPLITMODE)        ; a sky gradient moves with the horizon: draw it all
        dec a
        ld a,c
        jr nz,.s6
        ld a,TOPROW
.s6:    ld (crow),a
        ld l,a
        ld h,0
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        ld de,BUFFER
        add hl,de
        ex de,hl
        ld iy,c2back
c2row:  CHKEI
        ld a,(crow)             ; HL = LISTS + crow*32 + LP[crow]
        ld l,a
        ld h,ROWLP/256
        ld c,(hl)
        rrca
        rrca
        rrca
        ld h,a
        and $E0
        add a,c
        ld l,a
        ld a,h
        and $1F
        add a,LISTS/256
        ld h,a
        ld a,(crow)             ; this row's pattern page
        add a,ROWPG & 255
        ld c,a
        ld b,ROWPG/256
        ld a,(bc)
        ld b,a
        ld a,e
        ld ixl,a                ; row start (low byte)
        inc l
        ld c,(hl)
        inc l
        ld a,(bc)
        ld ixh,a
c2seg:  ld a,(hl)
        ld (c2x+1),a
        rrca
        rrca
        and $3F
        ld c,a
        ld a,e
        sub ixl                 ; j = bytes written this row (0..32)
        sub c
        cp 1
        jr z,c2thin
        add a,a
        add a,64
        ld (c2j+1),a
        ld a,ixh
c2j:    jp FILL2
c2back:
c2x:    ld a,0
        cp 128
        jr z,c2end
        inc l
        and 3
        jr z,c2al
        ex af,af'
        ld c,(hl)
        inc l
        ld a,(bc)
        ld c,a
        xor ixh
c2mix:  ex af,af'
        dec a
        jr z,c2s1
        dec a
        jr z,c2s2
        ex af,af'
        and $FC
        jr c2sx
c2s2:   ex af,af'
        and $F0
        jr c2sx
c2s1:   ex af,af'
        and $C0
c2sx:   xor c
        ld (de),a
        inc e
        ld ixh,c
        jp c2seg
c2al:   ld c,(hl)
        inc l
        ld a,(bc)
        ld ixh,a
        jp c2seg
c2thin: dec e
        inc l
        ld a,(c2x+1)
        and 3
        jr z,c2t0
        ex af,af'
        ld c,(hl)
        inc l
        ld a,(bc)
        ld c,a
        ld a,(de)
        xor c
        jr c2mix
c2t0:   ld c,(hl)
        inc l
        ld a,(bc)
        ld c,a
        xor a
        jr c2sx
c2end:  ld a,e
        or a
        jr nz,.r2
        inc d
.r2:    ld a,(crow)
        inc a
        ld (crow),a
        cp 64
        jp nz,c2row
        jp draw_skyline
; rect colour: A = pattern byte ($FF red, $AA blue, $55 yellow, $00 green)
set_rcol:
        ld (rc1+1),a
        ld (rc2+1),a
        ld (rc3+1),a
        ld (rc4+1),a
        ret

; rect: biased coords RX0..RX1 (screen x + 64), RY0..RY1 (screen y + 64), colour 3
rect:   ld a,(RX1)
        cp 64
        ret c
        ld a,(RX0)
        cp 192
        ret nc
        ld a,(RY1)
        cp 64
        ret c
        ld a,(RY0)
        cp 128
        ret nc
        cp 64+TOPROW            ; drawing over the static sky?
        jr nc,.ns
        ld a,1
        ld (SKYDIRTY),a
        ld (TOPCHG),a
.ns:    ld a,(RY0)              ; lowest row touched (plain-sky tracking)
        sub 64
        jr nc,.dm
        xor a
.dm:    ld hl,DMIN
        cp (hl)
        jr nc,.dm2
        ld (hl),a
.dm2:   ld a,(RX0)
        cp 64
        jr nc,.a
        ld a,64
.a:     sub 64
        ld (RX0),a
        ld a,(RX1)
        cp 192
        jr c,.b
        ld a,191
.b:     sub 64
        ld (RX1),a
        ld b,a
        ld a,(RX0)
        cp b
        jr z,.c
        ret nc
.c:     ld a,(RY0)
        cp 64
        jr nc,.d
        ld a,64
.d:     sub 64
        ld (RY0),a
        ld a,(RY1)
        cp 128
        jr c,.e
        ld a,127
.e:     sub 64
        ld (RY1),a
        ld b,a
        ld a,(RY0)
        cp b
        jr z,.f
        ret nc
.f:     ld a,(RX0)
        and 3
        add a,LMASK & 255
        ld l,a
        ld h,LMASK/256
        ld a,(hl)
        ld (MLEFT),a
        ld a,(RX1)
        and 3
        add a,4+(LMASK & 255)
        ld l,a
        ld a,(hl)
        ld (MRIGHT),a
        ld a,(RY0)
        ld (RY),a
.row:   ld a,(RY)
        ld l,a
        ld h,0
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        ld de,BUFFER
        add hl,de
        ld a,(RX0)
        rrca
        rrca
        and $1F
        ld c,a
        ld b,0
        add hl,bc
        ld a,(RX1)
        rrca
        rrca
        and $1F
        sub c
        jr nz,.wide
        ld a,(MLEFT)
        ld b,a
        ld a,(MRIGHT)
        and b
        ld b,a                  ; new = old ^ ((old ^ colour) & mask)
        ld a,(hl)
@rc1:   xor $FF
        and b
        xor (hl)
        ld (hl),a
        jr .nx
.wide:  ld b,a
        ld a,(MLEFT)
        ld c,a
        ld a,(hl)
@rc2:   xor $FF
        and c
        xor (hl)
        ld (hl),a
        inc hl
        dec b
        jr z,.last
@rc3:   ld a,$FF
.mid:   ld (hl),a
        inc hl
        djnz .mid
.last:  ld a,(MRIGHT)
        ld c,a
        ld a,(hl)
@rc4:   xor $FF
        and c
        xor (hl)
        ld (hl),a
.nx:    ld a,(RY1)
        ld b,a
        ld a,(RY)
        cp b
        ret z
        inc a
        ld (RY),a
        jp .row

; ---------------------------------------------------------------------
; MAKE_SKY_TOP: static sky image for rows 0..TOPROW-1 (bands 0 and 1)
; ---------------------------------------------------------------------
make_sky_top:
        ld de,SKYIMG
        ld c,0                  ; row
.r:     ld hl,(SKYTAB)
        ld a,c
        cp TOPROW/2
        jr c,.b0
        inc hl
.b0:    ld a,(hl)               ; colour
        bit 0,c
        jr z,.ev
        add a,16
.ev:    add a,PATTAB & 255
        ld l,a
        ld h,PATTAB/256
        ld a,(hl)
        ld b,32
.f:     ld (de),a
        inc de
        djnz .f
        inc c
        ld a,c
        cp TOPROW
        jr nz,.r
        ld a,1
        ld (SKYDIRTY),a
        ret

; ---------------------------------------------------------------------
; DRAW_SKYLINE: distant mountains just above the horizon, panning with
; the heading; written only on byte columns clear of track
; ---------------------------------------------------------------------
draw_skyline:
        ld a,(SKYLN)
        or a
        ret z
        ld a,(SPLIT)
        ld (.sp+1),a
        sub SKYL_H
        jr c,.y0
        cp TOPROW
        jr nc,.y1
.y0:    ld a,TOPROW
.y1:    ld (SKY_Y),a
        ld a,(HC)               ; s = 2*heading = 4q + 2sh
        add a,a
        ld c,a
        rrca
        rrca
        and $3F
        ld (.q+1),a
        ld a,c
        and 2                   ; B = 2sh
        ld b,a
        add a,a
        add a,a
        add a,a
        sub b                   ; 14*sh: pointer-table offset of this shift
        ld (.sb+1),a
.row:   ld a,(SKY_Y)
.sp:    cp 0
        ret nc
        ld (.cy+1),a
        ld e,a
        ld a,(.sp+1)
        sub e                   ; h = split - y
        dec a
        add a,a
.sb:    add a,0
        add a,SKYPTR & 255
        ld l,a
        ld h,SKYPTR/256
        ld a,(hl)
        inc l
        ld h,(hl)
        ld l,a
.q:     ld bc,0
        add hl,bc               ; HL = source bytes
        ld a,e                  ; DE = BUFFER + y*32
        rrca
        rrca
        rrca
        ld e,a
        and $1F
        add a,BUFFER/256
        ld d,a
        ld a,e
        and $E0
        ld e,a
.cy:    ld a,0
        push hl
        ld l,a
        ld h,ROWCL/256
        ld b,(hl)               ; CL
        add a,64
        ld l,a
        ld c,(hl)               ; CR
        pop hl
        ld a,b
        inc a
        jr nz,.cov
        ld bc,32                ; no track on this row
        ldir
        jr .nx
.cov:   ld a,b                  ; left of the track: min(32, (CL-64)/4) bytes
        sub 64
        jr c,.nol
        rrca
        rrca
        and $3F
        cp 33
        jr c,.lok
        ld a,32
.lok:   or a
        jr z,.nol
        push bc
        push hl
        push de
        ld c,a
        ld b,0
        ldir
        pop de
        pop hl
        pop bc
.nol:   ld a,c                  ; right of the track: from (CR-64)/4 + 1
        sub 64
        jr nc,.r1
        xor a
        jr .r2
.r1:    rrca
        rrca
        and $3F
        inc a
.r2:    cp 32
        jr nc,.nx
        ld c,a
        ld b,0
        add hl,bc
        ex de,hl
        add hl,bc
        ex de,hl
        ld a,32
        sub c
        ld c,a
        ldir
.nx:    ld hl,SKY_Y
        inc (hl)
        jp .row



; =====================================================================
;  RASTER ROAD (v0.11) - mirrors road_ref.py step for step
;  The road is 32 fixed depth slots (d = 32 near .. 1 far).  Walking from
;  near to far:  dx += CURV[section], x += dx  bends it;
;                dh += SLP[section] - SLP[here], h += dh  makes the hills.
;  Slot tables (page XCA):  +d XC (centre, screen x + 64)   +$40+d curve px
;                           +$80+d screen row               +$C0+d rows hidden below
;  Page SECL: +d section low, +$40+d section high, +$80+row slot of each screen row
;  Page ZTL (constants): +d depth low, +$40+d depth high, +$80+d half-width, +$C0+d rumble
; =====================================================================
render:
        ld hl,(CAM_I)           ; heading for the skyline, eased across the section
        ld de,TRK_H
        add hl,de
        ld a,(hl)
        ld (HC),a
        ld hl,(CAM_I)
        inc hl
        ld a,h
        and 1
        ld h,a
        add hl,de
        ld a,(HC)
        ld b,a
        ld a,(hl)
        sub b
        ld b,a
        ld a,(CAM_F)
        srl a
        ld c,a
        call mul8
        add hl,hl
        ld a,(HC)
        add a,h
        ld (HC),a
        ld hl,(CAM_I)           ; our own slope: a steady climb looks flat
        ld de,TRK_SL
        add hl,de
        ld a,(hl)
        ld (RS0),a
        ld hl,0
        ld (RDX),hl
        ld (RX),hl
        ld (RDH),hl
        ld (RH),hl
        ld a,(CAM_LAT)          ; the road slides under the craft: -lat px at the bottom row,
        neg                     ; tapering to nothing at the horizon
        ld h,a
        ld l,0
        ld (RLX),hl
        ld a,(CAM_LAT)
        call sext
        add hl,hl
        add hl,hl
        add hl,hl
        ld (RLS),hl
        ld a,64
        ld (RTOP),a
        ld a,ND
        ld (RD),a
.lp:    ld l,a                  ; section at this slot = camera + depth
        ld h,ZTL/256
        ld e,(hl)
        set 6,l
        ld d,(hl)
        ld a,(CAM_F)
        add a,e
        ld a,(CAM_I)
        adc a,d
        ld c,a
        ld a,(CAM_I+1)
        adc a,0
        and 1
        ld b,a                  ; BC = section
        res 6,l
        ld h,SECL/256
        ld (hl),c
        set 6,l
        ld (hl),b
        ld h,XCA/256            ; curve offset and road centre
        ld de,(RX)
        ld (hl),d
        res 6,l
        push hl
        ld hl,(RLX)
        add hl,de
        ld a,h
        add a,128
        pop hl
        ld (hl),a
        ld a,(RH+1)             ; screen row = HZ0 + d - h/1024
        sra a
        sra a
        ld e,a
        ld a,l
        add a,HZ0
        sub e
        ld e,a                  ; E = y
        set 7,l
        ld (hl),e
        set 6,l
        ld a,(RTOP)
        ld (hl),a
        ld d,a                  ; D = top
        ld a,e
        cp d
        jr nc,.hid              ; behind a crest
        cp RYMIN
        jr nc,.y1
        ld a,RYMIN
.y1:    ld (RTOP),a
        ld e,a
        ld a,d
        sub e
        jr z,.hid
        ld d,a                  ; rows y .. top-1 show this slot
        ld a,e
        add a,ROWMAP & 255
        ld l,a
        ld h,ROWMAP/256
        ld a,(RD)
.rm:    ld (hl),a
        inc l
        dec d
        jr nz,.rm
.hid:   ld hl,TRK_CV            ; bend: dx += curve, x += dx
        add hl,bc
        ld a,(hl)
        call sext
        ld de,(RDX)
        add hl,de
        ld (RDX),hl
        ld de,(RX)
        add hl,de
        ld (RX),hl
        ld hl,TRK_SL            ; hill: dh += slope - ours, h += dh
        add hl,bc
        ld a,(RS0)
        ld e,a
        ld a,(hl)
        sub e
        call sext
        ld de,(RDH)
        add hl,de
        ld (RDH),hl
        ld de,(RH)
        add hl,de
        ld (RH),hl
        ld hl,(RLX)
        ld de,(RLS)
        add hl,de
        ld (RLX),hl
        ld hl,RD
        dec (hl)
        ld a,(hl)
        jp nz,.lp
        ld a,(RTOP)
        ld (SPLIT),a
        ; ---- row lists: sky rows first (bands spread down to the horizon)
        sub TOPROW
        ld (RN),a
        ld hl,LISTS+TOPROW*32+1
        ld de,ROWPG+TOPROW
        ld c,TOPROW
        ld b,0
        ld a,2
        ld (RBAND),a
.sk:    ld a,(SPLIT)
        cp c
        jr z,.road
        push hl
        ld hl,(SKYTAB)
        ld a,(RBAND)
        add a,l
        ld l,a
        jr nc,.s1
        inc h
.s1:    ld a,(hl)
        pop hl
        bit 0,c
        jr z,.ev
        add a,16
.ev:    ld (hl),a
        inc l
        ld (hl),128
        ld a,l
        add a,31
        ld l,a
        jr nc,.s2
        inc h
.s2:    ld a,PATTAB/256
        ld (de),a
        inc e
        ld a,b
        add a,3
        ld b,a
        push hl
        ld hl,RN
        cp (hl)
        jr c,.s3
        sub (hl)
        ld b,a
        ld hl,RBAND
        inc (hl)
.s3:    pop hl
        inc c
        jr .sk
        ; ---- road rows
.road:  dec hl                  ; HL = list of row C, DE -> its ROWPG entry
        ld (RLP),hl
        ld (RPGP),de
        ld a,c
        ld (RROW),a
.rr:    add a,ROWMAP & 255
        ld l,a
        ld h,ROWMAP/256
        ld l,(hl)               ; slot
        ld h,SECL/256
        ld c,(hl)
        set 6,l
        ld b,(hl)               ; BC = section
        res 6,l
        ld a,RDP0/256           ; band page: two sections light, two dark
        bit 1,c
        jr z,.b0
        ld a,RDP1/256
.b0:    ld de,(RPGP)
        ld (de),a
        inc de
        ld (RPGP),de
        ld a,c                  ; surface: boost pad, jump ramp, start line or plain
        and 126
        cp 40
        jr nz,.n1
        ld a,c
        and 1
        add a,PAD_ID
        jr .cid
.n1:    ld a,c
        and 254
        cp 228
        jr nz,.n2
        ld a,c
        and 1
        add a,RAMP_ID
        jr .cid
.n2:    ld a,c
        or b
        ld a,LINE_ID
        jr z,.cid
        ld a,C_ID
.cid:   ld (.rc+1),a
        ld h,XCA/256
        ld a,(hl)               ; centre (screen x + 64)
        ld h,ZTL/256
        set 7,l
        ld e,(hl)               ; half-width
        set 6,l
        ld d,(hl)               ; rumble width
        ld c,a
        sub e
        jr nc,$+3
        xor a
        ld b,a
        sub d
        jr nc,$+3
        xor a
        call .clmp
        ld (RB0),a
        ld a,b
        call .clmp
        ld (RB1),a
        ld a,c
        add a,e
        jr nc,$+4
        ld a,255
        ld b,a
        call .clmp
        ld (RB2),a
        ld a,b
        add a,d
        jr nc,$+4
        ld a,255
        call .clmp
        ld (RB3),a
        ld hl,(RLP)
        ld a,(RROW)
        and 1
        rrca
        rrca
        rrca
        rrca
        ld d,a                  ; D = 16 on odd rows (other half of the dither)
        ld (hl),0
        inc l
        ld (hl),a               ; ground (G_ID = 0)
        ld b,0
        ld a,(RB0)
        ld c,R_ID
        call .emit
        jr nc,.end
        ld a,(RB1)
.rc:    ld c,0
        call .emit
        jr nc,.end
        ld a,(RB2)
        ld c,R_ID
        call .emit
        jr nc,.end
        ld a,(RB3)
        ld c,G_ID
        call .emit
.end:   inc l
        ld (hl),128
        ld hl,(RLP)
        ld de,32
        add hl,de
        ld (RLP),hl
        ld a,(RROW)
        inc a
        ld (RROW),a
        cp 64
        jp nz,.rr
        ret
.clmp:  sub 64                  ; screen x + 64 -> 0..128
        jr nc,.c1
        xor a
        ret
.c1:    cp 129
        ret c
        ld a,128
        ret
.emit:  cp 128                  ; A = x, C = colour; B = last x, HL -> last colour.  NC = off screen
        ret nc
        cp b
        jr z,.rep
        inc l
        ld (hl),a
        ld b,a
        inc l
.rep:   ld a,c
        add a,d
        ld (hl),a
        scf
        ret

; ---------------------------------------------------------------------
; RV_PROJECT: screen position, size, view and crest clip of every record
; in view (rivals, pickups, arrows, missile, mine).  R_D sections + R_FR
; ahead of the camera -> depth slot -> row, centre and width.
; ---------------------------------------------------------------------
rv_project:
        ld ix,RV
        ld b,NREC
.r:     push bc
        ld (ix+R_VIS),0
        ld a,(ix+R_D)
        cp 255
        jp z,.nx
        cp 16
        jr c,.near
        cp 21
        ld a,3
        jr c,.gd
        ld a,2
        jr .gd
.near:  rlca
        rlca
        rlca
        rlca
        ld c,a
        ld a,(ix+R_FR)
        rrca
        rrca
        rrca
        rrca
        and 15
        or c
        ld l,a
        ld h,DIDX/256
        ld a,(hl)
.gd:    ld e,a                  ; E = slot
        ld l,a
        ld h,XCA/256
        ld d,(hl)               ; D = road centre there
        set 7,l
        ld a,(hl)
        add a,65
        ld (ix+R_SY),a          ; sits on its row
        set 6,l
        ld a,(hl)
        add a,64
        ld (ix+R_YCL),a         ; rows from here down are behind a crest
        res 7,l
        ld a,(hl)               ; curve offset: which way the road there has turned
        sra a
        sra a
        sra a
        bit 7,a
        jr nz,.vn
        cp 3
        jr c,.vk
        ld a,2
        jr .vk
.vn:    cp -2
        jr nc,.vk
        ld a,-2
.vk:    add a,2
        ld (ix+R_VIEW),a
        ld a,e                  ; width: the craft is 24 px at slot 27
        rrca
        rrca
        rrca
        rrca
        and 15
        neg
        add a,e
        ld (ix+R_W),a
        push de
        ld b,(ix+R_LAT)         ; x = centre + lat * d / 32
        ld c,e
        call mul8
        add hl,hl
        add hl,hl
        add hl,hl
        pop de
        ld a,h
        or a
        jp m,.neg
        add a,d
        jr nc,.sok
        ld a,255
        jr .sok
.neg:   add a,d
        jr c,.sok
        xor a
.sok:   ld (ix+R_SX),a
        ld (ix+R_VIS),1
.nx:    ld de,32
        add ix,de
        pop bc
        dec b
        jp nz,.r
        ret

